<?php use App\Auth; use App\Support; $currentUser = Auth::user(); ?>
<div class="page-head"><div><span class="eyebrow">QUẢN LÝ TÀI KHOẢN</span><h1>Người dùng</h1><p>Mỗi tài khoản có kết nối, sản phẩm và danh sách đơn riêng.</p></div></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Tài khoản</th><th>Quyền sử dụng</th><th>Đơn hàng</th><th>Lần đăng nhập cuối</th><th>Trạng thái</th></tr></thead><tbody><?php foreach ($users as $item): ?><tr><td><b><?= Support::e($item['name']) ?></b><small><?= Support::e($item['email']) ?></small></td><td><?= Support::e(Support::roleLabel($item['role'])) ?></td><td><?= number_format((int)$item['order_count']) ?><small><?= (int)$item['running_count'] ?> đơn đang xử lý</small></td><td><?= Support::e($item['last_login_at'] ?: 'Chưa đăng nhập') ?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?= Support::csrfToken() ?>"><input type="hidden" name="user_id" value="<?= (int)$item['id'] ?>"><label class="switch"><input type="checkbox" name="is_active" <?= $item['is_active'] ? 'checked' : '' ?> <?= $item['id'] == ($currentUser['id'] ?? 0) ? 'disabled' : '' ?> onchange="this.form.submit()"><span></span><?= $item['is_active'] ? 'Đang sử dụng' : 'Đã tạm khoá' ?></label></form></td></tr><?php endforeach; ?></tbody></table></div></section>
